import React from 'react';

const cards = [
  {
    tag: 'DJAMANO INSIGHT IA',
    sub: "L'IA d'analyse et de décision stratégique",
    points: ['Prévisions événementielles', 'Analyse comportementale', 'Statistiques nationales'],
    bg: 'linear-gradient(135deg,#FF5A00 0%,#FF8A3D 100%)',
  },
  {
    tag: 'DJAMANO MATCH IA',
    sub: "L'IA de mise en relation intelligente",
    points: ['Recommandations prestataires', 'Réduction du temps de recherche', 'Valorisation des talents locaux'],
    bg: 'linear-gradient(135deg,#1a1a1a 0%,#333 100%)',
  },
  {
    tag: 'DJAMANO PULSE IA',
    sub: "L'IA d'engagement et d'expérience utilisateur",
    points: ['Recommandations personnalisées', 'Analyse de satisfaction', "Amélioration de l'expérience"],
    bg: 'linear-gradient(135deg,#2d2d2d 0%,#464646 100%)',
  },
];

const AISection = () => {
  const s = {
    section: { background: '#F0F0F0', padding: '90px 32px', fontFamily: 'Poppins, sans-serif' },
    wrapper: { maxWidth: 1200, margin: '0 auto' },
    eyebrow: {
      display: 'inline-flex', alignItems: 'center', gap: 8,
      background: '#FFF3ED', color: '#FF5A00',
      padding: '6px 14px', borderRadius: 30,
      fontSize: 12, fontWeight: 600, marginBottom: 20,
      fontFamily: 'Poppins, sans-serif',
    },
    title: {
      fontSize: 34, fontWeight: 800, color: '#111',
      fontFamily: 'Poppins, sans-serif', letterSpacing: '-0.6px',
      marginBottom: 14, lineHeight: 1.2,
    },
    orange: { color: '#FF5A00' },
    subtitle: {
      fontSize: 15, color: '#666', fontFamily: 'Poppins, sans-serif', fontWeight: 400,
      lineHeight: 1.72, maxWidth: 600, marginBottom: 52,
    },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 22 },
    card: (bg) => ({
      background: bg, borderRadius: 20, padding: '34px 28px',
      color: '#fff', display: 'flex', flexDirection: 'column', gap: 18,
    }),
    tag: {
      display: 'inline-block', background: 'rgba(255,255,255,.15)',
      color: '#fff', padding: '5px 14px', borderRadius: 20,
      fontSize: 10, fontWeight: 700, letterSpacing: '.6px',
      fontFamily: 'Poppins, sans-serif', alignSelf: 'flex-start',
    },
    cardSub: { fontSize: 15, fontWeight: 700, fontFamily: 'Poppins, sans-serif', lineHeight: 1.4 },
    divider: { height: 1, background: 'rgba(255,255,255,.18)' },
    points: { display: 'flex', flexDirection: 'column', gap: 12 },
    point: { display: 'flex', alignItems: 'center', gap: 10, fontSize: 13, fontFamily: 'Poppins, sans-serif', fontWeight: 400, opacity: .88 },
    dot: { width: 6, height: 6, borderRadius: '50%', background: 'rgba(255,255,255,.6)', flexShrink: 0 },
  };

  return (
    <section style={s.section}>
      <div style={s.wrapper}>
        <div style={s.eyebrow}>Intelligence Artificielle</div>
        <h2 style={s.title}>
          Djamano IA, <span style={s.orange}>l'intelligence qui propulse</span><br/>vos événements.
        </h2>
        <p style={s.subtitle}>
          Trois intelligences artificielles conçues pour organiser mieux, connecter plus intelligemment et impacter durablement l'écosystème événementiel.
        </p>
        <div style={s.grid}>
          {cards.map((c) => (
            <div key={c.tag} style={s.card(c.bg)}>
              <span style={s.tag}>{c.tag}</span>
              <div style={s.cardSub}>{c.sub}</div>
              <div style={s.divider} />
              <div style={s.points}>
                {c.points.map((p) => (
                  <div key={p} style={s.point}><span style={s.dot}/> {p}</div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default AISection;
